+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+import {createHash} from 'node:crypto';
+import {gunzipSync} from 'node:zlib';
+import {spawnSync} from 'node:child_process';
+const read=p=>JSON.parse(readFileSync(p,'utf8'));
+const e=read('docs/p9.0.7.2.12-boundary-decree-targets.json');
+const screen=read('docs/p9.0.7.2.12-normative-chain-candidates.json');
+const prev=read('docs/p9.0.7.2.11-85-case-worklist.json');
+const law=read('docs/p9.0.7.2.9-2026-primary-evidence.json');
+const gz=readFileSync('docs/p9.0.7.2.9-annual-census.json.gz');
+assert.equal(createHash('sha256').update(gz).digest('hex'),e.source_archive_sha256);
+assert.equal(JSON.parse(gunzipSync(gz)).total_publications,9254);
+assert.equal(e.schema_version,'p907212-targeted-boundary-and-normative-law-provenance-v1');
+assert.equal(screen.rows_screened,9254);
+assert.equal(screen.rows_selected,54);
+assert.equal(e.candidate_titles_screened,54);
+assert.equal(e.direct_atu_amendment_titles,2);
+assert.equal(e.related_secondary_reference_titles,1);
+assert.equal(screen.category_counts.ATU_FRAMEWORK_EXACT,2);
+assert.equal(screen.category_counts.ATU_FRAMEWORK_SECONDARY_REFERENCE,1);
+assert.equal(screen.category_counts.LOCAL_GOV_FRAMEWORK_EXACT,20);
+assert.equal(e.exact_city_boundary_decrees_found,2);
+assert.equal(screen.category_counts.SETTLEMENT_BOUNDARY_EXPLICIT,3);
+assert.equal(e.land_allotment_not_city_boundary_pub,'2025002341');
+for(const id of ['2023000445','2026000856','2025001424','2026000508']){
+ const target=[...e.direct_framework_acts,...e.city_boundary_acts].find(x=>x.publication_id===id);
+ const from=screen.candidates.find(x=>x.publication_id===id);
+ assert(target&&from);
+ for(const prop of ['source_url','title','act_number_date','publication_date'])assert.equal(target[prop],from[prop]);
+}
+assert.equal(e.direct_framework_acts[0].original_pdf_archived,false);
+const l114=e.direct_framework_acts[1];
+assert.equal(l114.publication_id,'2026000856');
+assert.equal(l114.in_force_at_cutoff,false);
+assert.equal(l114.exclude_from_current_operative_law,true);
+assert.equal(l114.primary_pdf_sha256,screen.law114_2026.archived_original_sha256);
+assert.equal(l114.operative_clause_verified_by_prior_stage,'SIX_MONTHS_AFTER_OFFICIAL_PUBLICATION');
+assert.equal(l114.exact_future_effective_instant_certified,false);
+assert.equal(screen.law114_2026.in_effect_on_2026_10_16,false);
+assert.equal(e.related_atu_reference[0].publication_id,'2023000446');
+const expected=['osm-r18941890','osm-r9659979'];
+assert.deepEqual(e.city_boundary_acts.map(x=>x.target_osm_actual_ids[0]),expected);
+for(const row of e.city_boundary_acts){
+ assert(prev.rows.some(x=>x.actual_id===row.target_osm_actual_ids[0]));
+ assert.equal(row.original_binary_recovered,false);
+ assert.equal(row.original_sha256,null);
+ assert.equal(row.complete_annex_recovered,false);
+ assert.equal(row.authoritative_vector_geometry_recovered,false);
+ assert.equal(row.full_osm_polygon_bound_by_primary_approval,false);
+ assert.equal(row.individual_identity_semantic_acceptance,'BLOCKED_INCOMPLETE');
+}
+assert.equal(e.direct_amendments_exhaustive_across_all_official_sources,false);
+assert.equal(e.local_framework_laws_individually_assessed,false);
+assert.equal(e.individual_issuer_authentication_complete,false);
+assert.equal(e.identity_count,85);
+assert.equal(e.accepted_identities,0);
+assert.equal(e.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(e.p91_import_allowed,false);
+assert.equal(e.actual_mutation_allowed,false);
+assert.equal(prev.adjudicated_cases,0);
+const check=spawnSync(process.execPath,['docs/p9.0.7.2.12-screen-normative-chain.mjs','--check'],{encoding:'utf8'});
+assert.equal(check.status,0,check.stderr||check.stdout);
+console.log('P907212_NORMATIVE_CHAIN_FAIL_CLOSED_PASS: 9254 screened / 54 title candidates / 2 exact ATU amendments / 2 official city-boundary decrees; originals+maps unverified; law114 not in force; 85 unadjudicated; P9.1 DENIED');
